exercises.starter:
import functools


def call_limit(n):
    def decorate(func):
        return func      # replace with a wrapper that counts calls
    return decorate


@call_limit(2)
def hello(name):
    """Greet someone."""
    return "hi " + name


print(hello("Ana"), hello("Ben"))

exercises.tests:
@call_limit(2)
def _hello(name, punctuation=""):
    """Greet someone."""
    return "hi " + name + punctuation

assert _hello("Ana") == "hi Ana"
assert _hello(name="Ben", punctuation="!") == "hi Ben!"
_raised = False
try:
    _hello("Cy")
except RuntimeError:
    _raised = True
assert _raised, "the third call must raise RuntimeError"
assert _hello.__name__ == "_hello" and _hello.__doc__ == "Greet someone."

_ran = []
@call_limit(1)
def _once():
    _ran.append(1)
    return 42

assert _once() == 42
try:
    _once()
except RuntimeError:
    pass
assert _ran == [1], "over the limit, the function itself must not run"

@call_limit(0)
def _never():
    return 1

try:
    _never()
    raise AssertionError("call_limit(0) must reject the first call")
except RuntimeError:
    pass

exercises.reference:
import functools


def call_limit(n):
    def decorate(func):
        calls = 0

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal calls
            if calls >= n:
                raise RuntimeError(f"{func.__name__} may be called at most {n} times")
            calls += 1
            return func(*args, **kwargs)
        return wrapper
    return decorate

exercises.solution:
```python
import functools

def call_limit(n):
    def decorate(func):
        calls = 0

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal calls
            if calls >= n:
                raise RuntimeError(f"{func.__name__} may be called at most {n} times")
            calls += 1
            return func(*args, **kwargs)
        return wrapper
    return decorate
```

`call_limit(2)` runs once and returns `decorate`; `decorate(hello)` runs once per decorated function and creates a fresh `calls` variable, which is why two decorated functions do not share a count. The wrapper checks the limit before calling, so the original never runs once the limit is reached, and `*args, **kwargs` plus `return` make it transparent to callers.
